Object.assign(DICT, Object.fromEntries(VOCAB_BLOCKS.flatMap(b => b.words.map(x => [x.word, x.translation]))));

let saved = [];
try {
  const raw = localStorage.getItem("citajSrpskiWords");
  const parsed = raw ? JSON.parse(raw) : [];
  saved = Array.isArray(parsed) ? parsed : [];
} catch (e) {
  saved = [];
}


const REVIEW_INTERVALS = [0, 1, 2, 4, 7, 14, 30]; // дни для коробок 1–6

function normalizeSavedWords(){
  let changed = false;
  saved = saved.map(x => {
    const y = {...x};
    if (!Number.isInteger(y.box) || y.box < 1 || y.box > 6) { y.box = 1; changed = true; }
    if (!y.nextReview) { y.nextReview = Date.now(); changed = true; }
    if (!y.translation || y.translation === 'Перевод пока не добавлен') {
      const tr = DICT[y.word];
      if (tr) { y.translation = tr; changed = true; }
    }
    if (!y.blockId) {
      const b = VOCAB_BLOCKS.find(block => block.words.some(v => v.word === y.word));
      if (b) { y.blockId = b.id; changed = true; }
    }
    return y;
  });
  if (changed) localStorage.setItem('citajSrpskiWords', JSON.stringify(saved));
}
normalizeSavedWords();

const $ = id => document.getElementById(id);
const normalize = w => w.toLowerCase().replace(/[„“”«».,!?;:()\[\]{}]/g, "").trim();

function findVerbInfo(w){
  const n=normalize(w);
  if(VERB_FORMS[n]) return VERB_FORMS[n];
  for(const v of Object.values(VERB_FORMS)){
    const forms=[v.lemma,v.past,v.present,v.future].filter(Boolean).join(' ').split(/\s+/).map(normalize);
    if(forms.includes(n)) return v;
  }
  return null;
}

function getTranslation(w){
  const n=normalize(w);
  if(DICT[n]) return DICT[n];
  const verb=findVerbInfo(n);
  if(verb) return verb.translation;
  const candidates=[];
  const suffixes=['ovima','evima','ama','ima','anje','enje','u','om','em','og','oj','im','om','as','os','es','us','a','e','i','o','y'];
  for(const suffix of suffixes){
    if(n.length>suffix.length+2 && n.endsWith(suffix)) candidates.push(n.slice(0,-suffix.length));
  }
  for(const c of candidates){ if(DICT[c]) return `${DICT[c]} (форма слова «${n}»)`; }
  return 'Перевод пока не добавлен';
}


function save(){
  localStorage.setItem("citajSrpskiWords", JSON.stringify(saved));
  const count = $("count");
  if (count) count.textContent = saved.length;
}

function view(id){
  document.querySelectorAll("main section").forEach(s => s.classList.add("hide"));
  const section = $(id);
  if (section) section.classList.remove("hide");
  window.scrollTo(0,0);
}


function vocabBlock(id){ return VOCAB_BLOCKS.find(b => b.id === id); }
function blockSavedWords(id){ return saved.filter(x => x.blockId === id); }
function addVocabWord(item, blockId){
  const existing=saved.find(x => x.word===item.word);
  if(existing){ if(!existing.blockId) existing.blockId=blockId; if(!existing.translation || existing.translation==='Перевод пока не добавлен') existing.translation=item.translation; return; }
  saved.push({word:item.word,translation:item.translation,added:new Date().toISOString(),box:1,nextReview:Date.now(),blockId});
}
function addWholeBlock(id){
  const b=vocabBlock(id); if(!b) return;
  b.words.forEach(x=>addVocabWord(x,id));
  save(); vocab();
}
function startBlockReview(id, mode='review'){
  const b=vocabBlock(id); if(!b) return;
  const list=blockSavedWords(id);
  if(!list.length){
    if(confirm('В этом блоке пока нет сохранённых слов. Добавить все 100 слов в «Мои слова»?')) addWholeBlock(id);
    return;
  }
  if(list.length < 2){ alert('В блоке пока меньше двух сохранённых слов. Добавь ещё слова или весь блок.'); return; }
  exerciseType=mode==='reverse'?'reverse':'choice';
  exercisePool=list;
  exerciseQueue=shuffle(list).slice(0, Math.min(20, list.length)).map(x=>x.word);
  exerciseIndex=0;
  renderExercise();
  view('review');
}
function vocab(){
  $('vocab-list').innerHTML = VOCAB_BLOCKS.map(b=>{
    const savedCount=blockSavedWords(b.id).length;
    return `<div class="card vocab-card">
      <div class="tag">${b.level}</div>
      <h3>${b.title}</h3>
      <p class="muted">${b.description}</p>
      <p><b>100 слов</b> · сохранено у тебя: <b>${savedCount}</b></p>
      <div class="vocab-actions">
        <button type="button" class="vocab-add" data-block="${b.id}">＋ Добавить весь блок</button>
        <button type="button" class="vocab-review" data-block="${b.id}">🔁 Повторять блок</button>
      </div>
      <details><summary>Показать слова</summary><div class="vocab-list">${b.words.map((x,i)=>`<div class="vocab-row"><span>${i+1}. <b>${x.word}</b></span><span>${x.translation}</span><button type="button" class="vocab-one" data-block="${b.id}" data-word="${x.word}">${saved.some(s=>s.word===x.word)?'✓':'＋'}</button></div>`).join('')}</div></details>
    </div>`;
  }).join('');
  view('vocab');
  document.querySelectorAll('.vocab-add').forEach(btn=>btn.addEventListener('click',()=>addWholeBlock(btn.dataset.block)));
  document.querySelectorAll('.vocab-review').forEach(btn=>btn.addEventListener('click',()=>startBlockReview(btn.dataset.block,'review')));
  document.querySelectorAll('.vocab-one').forEach(btn=>btn.addEventListener('click',()=>{
    const b=vocabBlock(btn.dataset.block); const item=b?.words.find(x=>x.word===btn.dataset.word); if(item){addVocabWord(item,b.id);save();vocab();}
  }));
}

function texts(){
  const local = TEXTS.filter(t => !t.level.includes('Исторический')).map((t,i) => {
    const realIndex = TEXTS.indexOf(t);
    const n=t.text.split(/[.!?]+/).filter(Boolean).length;
    return `<div class="card">
      <div class="tag">${t.level}</div>
      <h3>${t.title}</h3>
      <p>${t.ru}</p>
      <p class="muted">Большой учебный текст · ${n} предложений</p>
      <button type="button" class="read-text" data-index="${realIndex}">Читать</button>
    </div>`;
  }).join('');
  const historical = TEXTS.filter(t => t.level.includes('Исторический')).map(t => {
    const realIndex = TEXTS.indexOf(t);
    const n=t.text.split(/[.!?]+/).filter(Boolean).length;
    return `<div class="card real-source-card">
      <div class="tag">${t.level}</div>
      <h3>${t.title}</h3>
      <p>${t.ru}</p>
      <p class="muted">Оригинал уже встроен в сайт: можно читать здесь, нажимать на каждое слово, смотреть перевод и сохранять слова.</p>
      <p class="source">${t.source}</p>
      <p class="muted">${n} предложений</p>
      <button type="button" class="read-text" data-index="${realIndex}">📖 Читать на сайте</button>
      <a class="source-link" href="${t.url}" target="_blank" rel="noopener">Открыть первоисточник ↗</a>
    </div>`;
  }).join('');
  $("list").innerHTML = `
    <h3 class="library-heading">Учебные тематические тексты A2</h3>
    <p class="muted">Новые длинные тексты: учёба, прогулки по городу, культура и поездки на природу. Каждый содержит больше 100 предложений.</p>${local}
    <h3 class="library-heading">Реальные исторические тексты</h3>
    <p class="muted">Это оригинальные тексты Вука Караджича из Викизворника. Они встроены локально, поэтому больше не требуют загрузки страницы с другого сайта.</p>${historical}`;
}

function openRealSource(i){
  const t=REAL_SOURCES[i];
  window.open(t.url,'_blank','noopener');
}

function tokenize(text){ return text.split(/(\s+)/); }

function renderText(text){
  $("text").innerHTML = tokenize(text).map(part => {
    if (/^\s+$/.test(part)) return part;
    const clean = normalize(part);
    if (!clean) return part;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "word";
    btn.dataset.word = clean;
    btn.textContent = part;
    return btn.outerHTML;
  }).join("");
}

function openText(i){
  const t = TEXTS[i];
  $("title").textContent = t.title;
  $("level").textContent = `${t.level} · ${t.ru}`;
  $("source").textContent = t.source;
  renderText(t.text);
  $("popup").classList.add("hide");
  view("reader");
}

function getSerbianVoice(){
  const voices=window.speechSynthesis.getVoices();
  return voices.find(v=>/^sr(-|_)/i.test(v.lang)) || null;
}

function speakWord(w){
  if (!('speechSynthesis' in window)) {
    alert('Озвучка не поддерживается этим браузером.');
    return;
  }
  window.speechSynthesis.cancel();
  const voice=getSerbianVoice();
  if(!voice){
    alert('На этом устройстве не найден сербский голос. Я не буду подставлять английский голос, чтобы не искажать произношение. Установи/включи сербский голос в настройках синтеза речи Android, после чего кнопка будет использовать именно его.');
    return;
  }
  const u = new SpeechSynthesisUtterance(w);
  u.voice=voice;
  u.lang=voice.lang || 'sr-RS';
  u.rate=0.78;
  u.pitch=1;
  window.speechSynthesis.speak(u);
}

function speakText(text){
  if (!('speechSynthesis' in window)) {
    alert('Озвучка не поддерживается этим браузером.');
    return;
  }
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = 'sr-RS';
  u.rate = 0.88;
  window.speechSynthesis.speak(u);
}

function word(w){
  const translation = getTranslation(w);
  const exists = saved.some(x => x.word === w);
  const verb = findVerbInfo(w);
  const verbBlock = verb ? `
    <div class="verb-block">
      <div class="verb-title">Глагол: <b>${verb.lemma}</b> · ${verb.translation}</div>
      <div class="verb-grid">
        <div><span>Инфинитив</span><b>${verb.lemma} <small>— ${verb.translation}</small></b></div>
        <div><span>Прошедшее</span><b>${verb.past}</b></div>
        <div><span>Настоящее</span><b>${verb.present}</b></div>
        <div><span>Будущее</span><b>${verb.future}</b></div>
      </div>
      ${verb.note ? `<div class="verb-note">${verb.note}</div>` : ''}
    </div>` : '';
  $('popup').innerHTML = `
    <div class="popup-title">${w}</div>
    <div class="popup-translation">${translation}</div>
    ${verbBlock}
    <div class="popup-actions">
      <button type="button" id="speak-word">🔊 Слушать</button>
      <button type="button" id="add-word-button">${exists ? '✓ Уже в моих словах' : 'Добавить в мои слова'}</button>
    </div>`;
  $('popup').classList.remove('hide');
  $('speak-word').addEventListener('click', () => speakWord(w));
  const addButton = $('add-word-button');
  if (addButton && !exists) addButton.addEventListener('click', () => addWord(w));
}

function addWord(w){
  if (!saved.some(x => x.word === w)) {
    const sourceBlock = VOCAB_BLOCKS.find(b => b.words.some(x => x.word === w));
    saved.push({word:w, translation:getTranslation(w), added:new Date().toISOString(), box:1, nextReview:Date.now(), blockId:sourceBlock ? sourceBlock.id : undefined});
    save();
  }
  word(w);
}

